WITH account_stats AS (SELECT account_id, SUM(CASE WHEN merchant = '7-Eleven' THEN amount ELSE 0 END) AS 7_eleven_amount, MAX(amount) - MIN(amount) AS amount_range FROM transactions WHERE merchant IN ('7-Eleven', 'Lazada') GROUP BY account_id) SELECT a.id, a.customer_id, a.opened_date, as.7_eleven_amount, as.amount_range FROM accounts a LEFT JOIN account_stats as ON a.id = as.account_id ORDER BY opened_date;
